-- One-off data seed script -- NOT a numbered schema migration. Run manually
-- (e.g. `psql -f scripts/seed_trilha_multilang.sql`) against a database that
-- already has migration 000023 (starter_code_by_language column) applied.
-- Idempotent: safe to re-run, every statement is a plain UPDATE keyed by
-- slug.
--
-- Populates starter_code_by_language (python/javascript/go) for the 41
-- "Trilha de Evolucao" (trilha-*) challenges, then clears their pinned
-- language=python so the frontend language picker shows all three.
--
-- Generated by Claude Code; every JS/Go harness below was executed
-- (node / go run) against the challenge's sample test case and confirmed
-- byte-for-byte (after trim) before being included here. See the chat
-- transcript / final report for the two challenges with assumed business
-- rules (trilha-n4-carrinho-desconto discount %, trilha-n5-calculadora-frete
-- pricing formula) that could not be reverse-engineered from a single
-- sample case -- those only affect the throwaway test reference impls,
-- not the shipped stubs, which carry no business logic.

BEGIN;

-- trilha-n1-soma-media
UPDATE challenges
SET starter_code_by_language = jsonb_build_object(
