}

func media(a, b int) float64 {
	// TODO
	return 0
}
[[ASCEND::RUNNER]]
func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b int
	fmt.Fscan(reader, &a)
	fmt.Fscan(reader, &b)
	fmt.Println(somar(a, b))
	fmt.Printf("%.1f\n", media(a, b))
}$GO_1$
)
WHERE slug = 'trilha-n1-soma-media';

